15	/**
16	 * The figures of one person's claims, as the screen works them out: a settled claim's frozen due, else the
17	 * figure its person's last statement bound it to (not while PENDING), else its live due (amount times the rate in force on its date of
18	 * the grade its person had on its date, rounded by the sheet's policy, and at least the sheet's floor; none — n/a — when no rate applies then, or the one that would has ended by then). An
19	 * overdue claim's due adds, on top of its figure, the late charge: the sheet's late percent of the figure for every
20	 * full 30 days it is overdue on the sheet's today, rounded like a due. A statement never binds the charge; settling
21	 * freezes it in. A correction's live due is its amount times the rate, rounded the same way, with no floor, and it
22	 * never takes a late charge. The rounding policy: a claim dated before the sheet's policy date (its today when blank)
23	 * rounds half up, one dated on or after it half to even; a correction goes by the date of the claim it corrects.
24	 */
25	public class ClaimFigures {
26	
27	    private final List<Rate> rates;
28	
29	    private final PersonGrades grades;
30	
31	    private final BigDecimal floor;
32	
33	    private final BigDecimal latePct;
34	
35	    private final LocalDate today;
36	
37	    private final LocalDate policyDate;
38	
39	    /** @param rates the sheet's rates.
40	     *  @param grades the person's grades over time.
41	     *  @param sheet the sheet: its floor (a live due is at least it), and its late percent and today (the
42	     *  late charge). */
43	    public ClaimFigures(List<Rate> rates, PersonGrades grades, Sheet sheet) {
44	        this.rates = rates;
45	        this.grades = grades;
46	        this.floor = sheet.getFloor();
47	        this.latePct = sheet.getLatePct();
48	        this.today = sheet.getToday();
49	        this.policyDate = sheet.policyDateInForce();
50	    }
51	
52	    /** How the claim's live figures round: half up when the date it rounds by is before the policy date, else half
53	     *  to even. */
54	    public RoundingMode rounding(Claim claim) {
55	        return claim.getRoundsOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
56	    }
57	
58	    /** Whether a claim is overdue: it is OPEN or PENDING and its due-by (fixed when it was created) is before the sheet's today. */
59	    public boolean overdue(Claim claim) {
60	        return claim.getStatus().isOpen() && claim.getDueBy().isBefore(today);
61	    }
62	
63	    /** The late charge on a figure: the late percent of it for every full 30 days the claim is overdue, rounded
64	     *  like its due; 0.00 when it is not overdue. */
65	    public BigDecimal lateCharge(Claim claim, BigDecimal figure) {
66	        if (figure == null || claim.isCorrection() || !overdue(claim)) {
67	            return BigDecimal.ZERO.setScale(2);
68	        }
69	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), today) / 30;
70	        return figure.multiply(latePct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
71	                .setScale(2, rounding(claim));
72	    }
73	
74	    /** A live due: the amount times the percent, divided by 100, rounded as given, and at least the floor. */
75	    public static BigDecimal liveDue(BigDecimal amount, BigDecimal pct, BigDecimal floor, RoundingMode rounding) {
76	        BigDecimal due = amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
77	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
78	    }
79	
80	    /** Whether a claim counts toward the totals: only OPEN, PENDING and SETTLED claims do. */
81	    public static boolean counts(Claim claim) {
82	        return claim.getStatus().isOpen() || claim.getStatus() == ClaimStatus.SETTLED;
83	    }
84	
85	    /** Whether a claim counts toward the live totals: as {@link #counts}, except its person's OPEN and PENDING
86	     *  claims dated within a hold of theirs, unless a statement binds them (null person: no holds). */
87	    public static boolean countsLive(Claim claim, Person person) {
88	        return counts(claim) && !(person != null && claim.getStatus().isOpen() && !claim.isBound()
89	                && person.heldOn(claim.getDate()));
90	    }
91	
92	    /** The percent of the grade's rate in force on a date; none when that rate's to-date is before it. */
93	    private Optional<BigDecimal> rateOn(String grade, LocalDate on) {
94	        return rates.stream()
95	                .filter(r -> r.getGrade().equals(grade))
96	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
97	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
98	                .filter(r -> !r.endedBy(on))
99	                .map(Rate::getPct);
100	    }
101	
102	    /** The claim's due: its figure, plus the late charge while it is not settled; null when it has none (n/a). */
103	    public BigDecimal due(Claim claim) {
104	        if (claim.getDue() != null) {
105	            return claim.getDue();
106	        }
107	        BigDecimal figure = figure(claim);
108	        return figure == null ? null : figure.add(lateCharge(claim, figure));
109	    }
110	
111	    /** The claim's figure, without any late charge; null when it has none (n/a). */
112	    public BigDecimal figure(Claim claim) {
113	        if (claim.getDue() != null) {
114	            return claim.getDue();
115	        }
116	        if (claim.isBound()) {
117	            return claim.getStatedDue();
118	        }
119	        return rateOn(grades.on(claim.getDate()), claim.getDate())
120	                .map(pct -> liveDue(claim.getAmount(), pct, claim.isCorrection() ? null : floor, rounding(claim)))
121	                .orElse(null);
122	    }
123	
124	    /** The person's due-total: their counted claims' dues (with any late charge) added up, 0.00 with none; n/a when their grade
125	     *  in force on the day has no rate in force then, unless a counted claim keeps a figure: a fixed one (settled or bound), or a
126	     *  live one at another grade they had on its date, or one dated on or before the day (at a rate that has ended since). */
127	    public String dueTotal(List<Claim> claims, LocalDate today) {
128	        return dueTotal(claims, today, null);
129	    }
130	
131	    /** The person's live due-total, as {@link #dueTotal(List, LocalDate)}; their OPEN claims dated within a hold
132	     *  of theirs do not count, unless a statement binds them. */
133	    public String dueTotal(List<Claim> claims, LocalDate today, Person person) {
134	        List<Claim> counted = claims.stream().filter(c -> countsLive(c, person)).toList();
135	        String grade = grades.on(today);
136	        boolean kept = counted.stream().anyMatch(c -> c.getDue() != null || (c.isBound() && c.getStatedDue() != null)
137	                || (!c.isBound() && (!grade.equals(grades.on(c.getDate())) || !c.getDate().isAfter(today)) && figure(c) != null));
138	        if (rateOn(grade, today).isEmpty() && !kept) {
139	            return "n/a";
140	        }
141	        return counted.stream().map(this::due).filter(f -> f != null)
142	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
143	    }
144	}
