359	/**
360	 * The sheet's figures at one moment, as the screen shows them: each person's claimed and due-total, in the
361	 * order they were added, and the sheet's claimed-total and due-total (everyone's added up, skipping n/a).
362	 * A person's OPEN and PENDING claims dated within a hold of theirs count in none of them, unless a statement binds them.
363	 */
364	public class Rollup {
365	
366	    /** One person's figures. */
367	    public record Figures(String name, String claimed, String dueTotal) {
368	    }
369	
370	    private final Map<Long, Figures> people;
371	    private final String claimedTotal;
372	    private final String dueTotal;
373	
374	    private Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
375	        this.people = people;
376	        this.claimedTotal = claimedTotal;
377	        this.dueTotal = dueTotal;
378	    }
379	
380	    /** Works out the sheet's figures now; a sheet not yet stored has none. */
381	    public static Rollup of(String sheetId, SheetRepository sheets, PersonRepository persons,
382	            ClaimRepository claims, RateRepository rates, PersonGradeRepository grades) {
383	        String id = sheetId.trim();
384	        Optional<Sheet> sheet = sheets.findById(id);
385	        Map<Long, Figures> people = new LinkedHashMap<>();
386	        BigDecimal claimedTotal = BigDecimal.ZERO;
387	        BigDecimal dueTotal = BigDecimal.ZERO;
388	        if (sheet.isPresent()) {
389	            List<Claim> all = claims.findBySheetIdOrderByIdDesc(id);
390	            var sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(id);
391	            Map<Long, List<PersonGrade>> dated = grades.datedOnSheet(id);
392	            for (Person person : persons.findBySheetIdOrderByIdAsc(id)) {
393	                List<Claim> mine = all.stream().filter(c -> person.getId().equals(c.getPersonId())).toList();
394	                BigDecimal claimed = mine.stream().filter(c -> ClaimFigures.countsLive(c, person)).map(Claim::getAmount)
395	                        .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
396	                String due = new ClaimFigures(sheetRates,
397	                        new PersonGrades(person.getGrade(), dated.getOrDefault(person.getId(), List.of())), sheet.get())
398	                        .dueTotal(mine, sheet.get().getToday(), person);
399	                people.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), due));
400	                claimedTotal = claimedTotal.add(claimed);
401	                if (!"n/a".equals(due)) {
402	                    dueTotal = dueTotal.add(new BigDecimal(due));
403	                }
404	            }
405	        }
406	        return new Rollup(people, claimedTotal.setScale(2).toPlainString(), dueTotal.setScale(2).toPlainString());
407	    }
408	
409	    /** The audit lines telling how the figures moved from before to now: one per person whose figures changed
410	     *  (or who is new), then the totals when they changed; none when nothing moved. */
411	    public List<String> changesSince(Rollup before, String sheetId, String user) {
412	        String head = " sheet=" + sheetId.trim() + " by=" + user;
413	        List<String> lines = new ArrayList<>();
414	        people.forEach((id, now) -> {
415	            Figures was = before.people.get(id);
416	            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
417	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
418	                        + " due-total=" + now.dueTotal());
419	            }
420	        });
421	        if (!before.claimedTotal.equals(claimedTotal) || !before.dueTotal.equals(dueTotal)) {
422	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal);
423	        }
424	        return lines;
