602	import net.officefloor.hq.app.sheet.Sheet;
603	import net.officefloor.plugin.variable.Out;
604	import org.springframework.web.bind.annotation.RequestBody;
605	
606	/** Reads the settings form from the body; refuses a clerk limit or floor that is negative or has more than two
607	 *  decimals, and terms that are not a whole number of days, and a late percent that is negative or has more than two decimals, and a policy date or period numbering from that is not a calendar date
608	 *  (YYYY-MM-DD). A blank clerk limit means no limit; a blank floor is
609	 *  1.00; blank terms are 14; a blank late percent is 0.00; a blank policy date is the sheet's today; a blank period numbering from is off. A grade's terms must be a whole number of days, or blank (the grade uses the sheet's terms). A key left out is not changed. */
610	public class ValidateSettings {
611	
612	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
613	
614	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
615	
616	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingsException {
617	        String limit = request == null ? null : request.clerkLimit();
618	        String floor = request == null ? null : request.floor();
619	        BigDecimal limitValue = null;
620	        if (limit != null && !limit.trim().isEmpty()) {
621	            if (!AMOUNT.matcher(limit.trim()).matches()) {
622	                throw new InvalidSettingsException("The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank.");
623	            }
624	            limitValue = new BigDecimal(limit.trim()).setScale(2);
625	        }
626	        BigDecimal floorValue = Sheet.DEFAULT_FLOOR;
627	        if (floor != null && !floor.trim().isEmpty()) {
628	            if (!AMOUNT.matcher(floor.trim()).matches()) {
629	                throw new InvalidSettingsException("The floor must be an amount, 0.00 or more, with up to two decimals, or blank.");
630	            }
631	            floorValue = new BigDecimal(floor.trim()).setScale(2);
632	        }
633	        String terms = request == null ? null : request.terms();
634	        int termsValue = Sheet.DEFAULT_TERMS;
635	        if (terms != null && !terms.trim().isEmpty()) {
636	            if (!DAYS.matcher(terms.trim()).matches()) {
637	                throw new InvalidSettingsException("The terms must be a whole number of days, 0 or more, or blank.");
638	            }
639	            termsValue = Integer.parseInt(terms.trim());
640	        }
641	        String late = request == null ? null : request.latePct();
642	        BigDecimal lateValue = Sheet.DEFAULT_LATE_PCT;
643	        if (late != null && !late.trim().isEmpty()) {
644	            if (!AMOUNT.matcher(late.trim()).matches()) {
645	                throw new InvalidSettingsException("The late percent must be a percent, 0.00 or more, with up to two decimals, or blank.");
646	            }
647	            lateValue = new BigDecimal(late.trim()).setScale(2);
648	        }
649	        String policy = request == null ? null : request.policyDate();
650	        LocalDate policyValue = null;
651	        if (policy != null && !policy.trim().isEmpty()) {
652	            try {
653	                policyValue = LocalDate.parse(policy.trim());
654	            } catch (DateTimeParseException e) {
655	                throw new InvalidSettingsException("The policy date must be a date (YYYY-MM-DD), or blank.");
656	            }
657	        }
658	        String numbering = request == null ? null : request.periodNumberingFrom();
659	        LocalDate numberingValue = null;
660	        if (numbering != null && !numbering.trim().isEmpty()) {
661	            try {
662	                numberingValue = LocalDate.parse(numbering.trim());
663	            } catch (DateTimeParseException e) {
664	                throw new InvalidSettingsException("The period numbering from must be a date (YYYY-MM-DD), or blank.");
665	            }
666	        }
667	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
668	        if (request != null) {
669	            gradeTerms(gradeTerms, "A", request.termsA());
670	            gradeTerms(gradeTerms, "B", request.termsB());
671	            gradeTerms(gradeTerms, "C", request.termsC());
672	        }
673	        body.set(new SettingsInput(limit != null, limitValue, floor != null, floorValue, terms != null, termsValue,
674	                late != null, lateValue, policy != null, policyValue,
675	                numbering != null, numberingValue, gradeTerms));
676	    }
677	
678	    /** Adds a grade's terms when the form sets them: blank is none (the sheet's terms). */
679	    private static void gradeTerms(Map<String, Integer> gradeTerms, String grade, String terms) throws InvalidSettingsException {
680	        if (terms == null) {
681	            return;
682	        }
683	        Integer value = null;
684	        if (!terms.trim().isEmpty()) {
685	            if (!DAYS.matcher(terms.trim()).matches()) {
686	                throw new InvalidSettingsException("The terms of grade " + grade + " must be a whole number of days, 0 or more, or blank.");
687	            }
688	            value = Integer.parseInt(terms.trim());
689	        }
690	        gradeTerms.put(grade, value);
691	    }
692	}
