import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, type Person } from '../people/people';
import { countsLive, holdsOf, isBound, useClaims, type Claim } from '../claims/claims';
import { useSettings, type Settings } from '../roles/roles';
import { chargedOf, rateOn, sumDue, useRates, type Rate } from './rates';

// A person's due-total: the sum of their counted claims' dues, each already rounded (a settled claim's
// frozen due, else the figure their last statement bound it to, else its live due, at least the sheet's floor; plus
// an overdue claim's late charge; each claim at the grade they had on its date) — 0.00 with nothing that counts.
// When their grade in force on the sheet's today has no rate in force then it is n/a, unless a counted claim keeps
// a figure — settled, bound, or live at another grade they had on its date, or live
// on or before the sheet's today at a rate that has ended since: then it is the sum of the figures there are. Their unbound OPEN claims dated within a hold of theirs do not count. The sheet's due-total is everyone's added up, skipping n/a.
export function personDue(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): string {
  const mine = claims.filter((c) => c.personId === person.id && countsLive(c, holdsOf([person])));
  const grade = gradeOn(person, today);
  const kept = (c: Claim) => c.due !== null || (isBound(c) && c.statedDue !== null)
    || (!isBound(c) && (gradeOn(person, c.date) !== grade || (today !== undefined && c.date <= today)) && chargedOf(c, rates, gradeOn(person, c.date), settings, today) !== 'n/a');
  if (rateOn(rates, grade, today) === undefined && !mine.some(kept)) {
    return 'n/a';
  }
  return sumDue(mine.map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today)));
}

function DueHeader() {
  return <th>Due</th>;
}

function PersonDue({ person }: { person: Person }) {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return <td data-testid="person-due-total">{personDue(person, claims.data ?? [], rates.data, today, settings.data)}</td>;
}

function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  if (!user || !sheet) return null;
  const total = sumDue((people.data ?? []).map((p) => personDue(p, claims.data ?? [], rates.data, today, settings.data)));
  return (
    <p>
      Due in total <strong data-testid="rollup-due-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 15, Component: DueHeader }),
  PersonCells.fill({ order: 15, Component: PersonDue }),
  HomeMain.fill({ order: 31, Component: DueTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { dueByOf, isBound, isOverdue, type Claim } from '../claims/claims';
import type { Settings } from '../roles/roles';
import { useCurrentSheet } from '../session/session';

/** A grade's rate as the store holds it: the percent with two decimals, from a date on (YYYY-MM-DD; null
 *  when it applies from the beginning of time), through a to-date (null when it has no end). */
export type Rate = { grade: string; pct: string; from: string | null; to: string | null };

export const ratesQueryKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

export const ratesPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rates`;

/** The sheet's rates, by grade, then by from-date (a rate with none first). */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesQueryKey(sheet ?? ''),
    queryFn: () => getJson<Rate[]>(ratesPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The percent ("12.50") of a grade's rate in force on a date (YYYY-MM-DD): the one whose from-date is the
 *  latest on or before it, a rate with no from-date applying from the beginning of time — or undefined when
 *  no rate applies then, or when that one's to-date is before the date. */
export function rateOn(rates: Rate[] | undefined, grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (!found || (found.from ?? '') <= (r.from ?? '')) found = r;
  }
  if (found?.to != null && found.to < date) return undefined;
  return found?.pct;
}

/** Whether a claim's live figures round half up: the date it rounds by (a correction's is the date of the claim it
 *  corrects) is before the sheet's policy date (its today when blank); else they round half to even. */
export function roundsHalfUp(c: Claim, settings: Settings | undefined, today: string | undefined): boolean {
  const policy = settings?.policyDate || today;
  return policy !== undefined && (c.roundsOn ?? c.date) < policy;
}

/** A claim's figure: a settled claim's frozen due, else the figure its person's last statement bound it to (not while PENDING),
 *  else its live due at the rate on its date of the grade (its person's grade on its date), at least the sheet's floor ("n/a" when it has none),
 *  rounded by the sheet's policy; a correction's live due has no floor. */
export function figureOf(c: Claim, rates: Rate[] | undefined, grade: string, floor: string | null | undefined,
  halfUp = false): string {
  if (c.due !== null) return c.due;
  if (isBound(c)) return c.statedDue ?? 'n/a';
  const due = dueOf(c.amount, rateOn(rates, grade, c.date), halfUp);
  return c.corrects !== null ? due : atLeast(due, floor);
}

/** A claim's due: a settled claim's frozen due, else its figure plus its late charge — the sheet's late percent
 *  of the figure for every full 30 days it is overdue on the sheet's today, rounded like a due ("n/a" when it
 *  has no figure). A statement binds only the figure: the charge keeps following the sheet's today. A correction never
 *  takes a late charge. */
export function chargedOf(c: Claim, rates: Rate[] | undefined, grade: string, settings: Settings | undefined,
  today: string | undefined): string {
  const halfUp = roundsHalfUp(c, settings, today);
  const figure = figureOf(c, rates, grade, settings?.floor, halfUp);
  if (c.due !== null || c.corrects !== null || figure === 'n/a') return figure;
  if (today === undefined || !isOverdue(c, today)) return figure;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueByOf(c)}T00:00:00Z`)) / 86_400_000;
  const periods = Math.floor(days / 30);
  const charge = dueOf(formatCents(hundredths(figure) * BigInt(periods)), settings?.latePct ?? '0.00', halfUp);
  return formatCents(hundredths(figure) + hundredths(charge));
}

/** A due raised to the floor when below it ("n/a" stays n/a; no floor leaves it as it is). */
export function atLeast(due: string, floor: string | null | undefined): string {
  if (due === 'n/a' || floor == null || floor === '') return due;
  return hundredths(due) < hundredths(floor) ? formatCents(hundredths(floor)) : due;
}

/** A two-decimal string ("12.50") in hundredths, exactly. */
const hundredths = (s: string) => BigInt(Math.round(Number(s) * 100));

/**
 * The due on an amount: amount times the percent, divided by 100, rounded half to even (or half up, away from
 * zero) to two decimals — "n/a" when there is no percent. Computed in whole hundredths, so it is exact.
 */
export function dueOf(amount: string, pct: string | undefined, halfUp = false): string {
  if (pct === undefined) return 'n/a';
  // hundredths of the amount times hundredths of the percent = the due in millionths of a percent;
  // dividing by 10000 gives cents.
  const product = hundredths(amount) * hundredths(pct);
  const negative = product < 0n;
  const magnitude = negative ? -product : product;
  const rest = magnitude % 10000n;
  let cents = magnitude / 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return formatCents(negative ? -cents : cents);
}

/** Whole cents as a two-decimal string. */
export function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const m = negative ? -cents : cents;
  return `${negative ? '-' : ''}${m / 100n}.${(m % 100n).toString().padStart(2, '0')}`;
}

/** Adds up two-decimal amounts, skipping "n/a". */
export function sumDue(dues: string[]): string {
  return formatCents(dues.filter((d) => d !== 'n/a').reduce((n, d) => n + hundredths(d), 0n));
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { settingsPath, settingsQueryKey, useSettings, type Settings } from './roles';

type Key = 'clerkLimit' | 'floor' | 'terms' | 'latePct' | 'policyDate' | 'periodNumberingFrom' | 'termsA' | 'termsB' | 'termsC';

/** The grades that may have their own terms, and the setting key of each. */
const GRADE_TERMS = [
  { grade: 'A', key: 'termsA' },
  { grade: 'B', key: 'termsB' },
  { grade: 'C', key: 'termsC' },
] as const;
type Drafts = Partial<Record<Key, string>>;

// The sheet's settings: the clerk limit in force (blank when there is none), the floor in force (a claim's live
// due is at least it), the terms in force (a claim is due by its date plus that many days), the late percent in force (an overdue
// claim's due gains it of its figure for every full 30 days overdue), the policy date (a claim dated before it rounds half
// up, one on or after it half to even; blank: the sheet's today), the period numbering from (while the sheet's today is on or after it, a claim
// opened is numbered within its period: P1-1, X-1 for no period; blank: off), each grade's own terms (blank: the sheet's terms;
// a claim's due-by is fixed when it is created, from the terms of its person's grade on its date), and the form that sets them. A clerk settles a claim only when its due is at or below the
// limit; a steward settles anything. Each field shows the value in force until it is typed in (or focused); saving sets only
// the fields typed in (all of them when none was).
function SheetSettings() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const settings = useSettings();
  const [drafts, setDrafts] = useState<Drafts>({});
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (body: Drafts) => putJson<Settings>(settingsPath(sheet ?? ''), body, user),
    onSuccess: async (_saved, sent) => {
      await queryClient.invalidateQueries({ queryKey: settingsQueryKey(sheet ?? '') });
      // Keep what was typed in while the save was on its way; drop only the drafts it saved.
      setDrafts((d) => Object.fromEntries(Object.entries(d).filter(([k, v]) => sent[k as Key] !== v)) as Drafts);
    },
  });
  const submit = useSubmitOnce(save);

  if (!user || !sheet) return null;
  const current: Record<Key, string> = {
    clerkLimit: settings.data?.clerkLimit ?? '',
    floor: settings.data?.floor ?? '',
    terms: settings.data?.terms ?? '',
    latePct: settings.data?.latePct ?? '',
    policyDate: settings.data?.policyDate ?? '',
    periodNumberingFrom: settings.data?.periodNumberingFrom ?? '',
    termsA: settings.data?.termsA ?? '',
    termsB: settings.data?.termsB ?? '',
    termsC: settings.data?.termsC ?? '',
  };
  const valueOf = (key: Key) => drafts[key] ?? current[key];
  const edit = (key: Key) => (e: { currentTarget: HTMLInputElement }) => {
    const value = e.currentTarget.value;
    setDrafts((d) => ({ ...d, [key]: value }));
    save.reset();
  };
  // A field focused counts as typed in, even when left as it is (filling a blank field with blank changes nothing).
  const touch = (key: Key) => () => setDrafts((d) => (key in d ? d : { ...d, [key]: current[key] }));
  return (
    <section data-testid="settings">
      <h2>Settings</h2>
      <p>
        Clerk limit: <span data-testid="setting-clerk-limit-current">{settings.data?.clerkLimit ?? ''}</span>
      </p>
      <p>
        Floor: <span data-testid="setting-floor-current">{settings.data?.floor ?? ''}</span>
      </p>
      <p>
        Terms (days): <span data-testid="setting-terms-current">{settings.data?.terms ?? ''}</span>
      </p>
      <p>
        Late percent: <span data-testid="setting-late-pct-current">{settings.data?.latePct ?? ''}</span>
      </p>
      <p>
        Policy date: <span data-testid="setting-policy-date-current">{settings.data?.policyDate ?? ''}</span>
      </p>
      <p>
        Period numbering from:{' '}
        <span data-testid="setting-period-numbering-from-current">{settings.data?.periodNumberingFrom ?? ''}</span>
      </p>
      {GRADE_TERMS.map(({ grade, key }) => (
        <p key={grade}>
          Terms of grade {grade} (days; blank: the sheet's):{' '}
          <span data-testid={`setting-terms-${grade}-current`}>{settings.data?.[key] ?? ''}</span>
        </p>
      ))}
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit(Object.keys(drafts).length > 0 ? drafts : { ...current });
        }}
      >
        <input
          data-testid="setting-clerk-limit"
          placeholder="Clerk limit (blank: no limit)"
          inputMode="decimal"
          value={valueOf('clerkLimit')}
          onChange={edit('clerkLimit')}
          onInput={edit('clerkLimit')}
          onFocus={touch('clerkLimit')}
        />
        <input
          data-testid="setting-floor"
          placeholder="Floor (blank: 1.00)"
          inputMode="decimal"
          value={valueOf('floor')}
          onChange={edit('floor')}
          onInput={edit('floor')}
          onFocus={touch('floor')}
        />
        <input
          data-testid="setting-terms"
          placeholder="Terms in days (blank: 14)"
          inputMode="numeric"
          value={valueOf('terms')}
          onChange={edit('terms')}
          onInput={edit('terms')}
          onFocus={touch('terms')}
        />
        <input
          data-testid="setting-late-pct"
          placeholder="Late percent (blank: 0.00)"
          inputMode="decimal"
          value={valueOf('latePct')}
          onChange={edit('latePct')}
          onInput={edit('latePct')}
          onFocus={touch('latePct')}
        />
        <input
